package com.example.practice;

import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISOUtil;

/**
 * The acquirer's host as the client's integration tests see it: it answers each request the way
 * the host's interface document describes. The tests keep every request they send, to check later
 * what the client asked for.
 */
public class HostSimulator {
    /** The fields a response echoes, from the interface document. */
    static final int[] ECHOED = { 2, 3, 4, 7, 11, 12, 13, 32, 37, 41, 42, 49 };

    private int approvals;

    /** The host's answer to {@code request}, with {@code responseCode} in field 39. */
    public ISOMsg respond(ISOMsg request, String responseCode) throws ISOException {
        ISOMsg response = echoed(request);
        answerMti(response);
        response.set(39, responseCode);
        if ("00".equals(responseCode))
            response.set(38, ISOUtil.zeropad(Integer.toString(++approvals), 6));
        return response;
    }

    /** A new message with the request's MTI and the fields the response echoes. */
    ISOMsg echoed(ISOMsg request) {
        ISOMsg response = (ISOMsg) request.clone(0);
        for (int f : ECHOED) {
            if (request.hasField(f))
                response.set(f, request.getString(f));
        }
        return response;
    }

    /** Turns the MTI the response carries (still the request's) into the response's MTI. */
    void answerMti(ISOMsg response) throws ISOException {
        response.setResponseMTI();
    }
}

import com.example.practice.HostSimulator;
import org.jpos.iso.ISOMsg;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            HostSimulator host = new HostSimulator();
            ISOMsg purchase = request("0200", "040501");
            ISOMsg approved = host.respond(purchase, "00");
            System.out.println("purchase answer: " + approved.getMTI() + " rc=" + approved.getString(39) + " approval=" + approved.getString(38));
            System.out.println("echoes STAN/RRN: " + approved.getString(11) + " / " + approved.getString(37));
            System.out.println("carries field 22 or 52: " + (approved.hasField(22) || approved.hasField(52)));
            System.out.println("advice repeat answer: " + host.respond(request("0221", "040502"), "00").getMTI());
            System.out.println("reversal repeat answer: " + host.respond(request("0421", "040503"), "05").getMTI());
            System.out.println("kept request: " + purchase.getMTI() + ", has field 39: " + purchase.hasField(39));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static ISOMsg request(String mti, String stan) throws Exception {
        ISOMsg m = new ISOMsg(mti);
        m.set(2, "4000002500003155");
        m.set(3, "000000");
        m.set(4, "000000002210");
        m.set(11, stan);
        m.set(22, "051");
        m.set(37, "702201" + stan);
        m.set(41, "40330005");
        m.set(52, new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 });
        m.set(49, "826");
        return m;
    }
}

